css:
 .columnbox {
  font-family: "Noto Sans JP", sans-serif;
  width: 100%;
  margin-block-start: 100px;
  padding: 10px;
  background: linear-gradient(to right, #c8a5d6 0%, #b292bf 100%);
  box-sizing: border-box;
}

 .columnbox__bg {
  width: min(100%, 2000px);
  margin-inline: auto;
  background-repeat: no-repeat;
  background-position: bottom left, bottom right;
  background-size: auto 70%;
  background-image: url(/uploads/a4ad660fa35ff5bbd7bfc5e9eb29a3b460b3e28e4ccf951785eb91456b55f904.png), url(/uploads/c30362c15970e812c6f96c37341f407c35b84a7db0de01b20f8b066632afb84e.png);
}

 .columnbox__list {
  display: grid;
  overflow-x: clip;
  justify-content: center;
  align-content: start;
  align-items: center;
  grid-template-columns: repeat(3, 33.3333333333%);
  gap: 1em 0;
  width: min(100%, 1280px);
  margin-inline: auto;
}

 .columnbox__item {
  position: relative;
  display: grid;
  grid-row: span 3;
  grid-template-rows: subgrid;
  width: 100%;
  padding-block: 1.5em;
  padding-right: clamp(10px, 2.5vw, 40px);
  padding-left: clamp(10px, 2.5vw, 40px);
  box-sizing: border-box;
}

 .columnbox__item:first-child {
  padding-left: 0;
}

 .columnbox__item:last-child {
  padding-right: 0;
}

 .columnbox__item:last-child::after {
  content: none;
}

 .columnbox__item::after {
  position: absolute;
  top: 50%;
  right: 0;
  display: block;
  height: 80%;
  content: "";
  translate: 0 -50%;
  border-right: 3px dotted rgba(255, 255, 255, 0.3);
}

 .columnbox__item-title {
  display: flex;
  align-items: center;
  width: 100%;
  column-gap: clamp(8px, 1vw, 16px);
  justify-content: center;
}

 .columnbox__item-title::before,
 .columnbox__item-title::after {
  content: "";
  width: 100%;
  max-width: 43px;
  height: 2px;
  border-top: 1px solid rgba(255, 255, 255, 0.5);
  border-bottom: 1px solid rgba(255, 255, 255, 0.5);
}

 .columnbox__item-title-inn .txt {
  font-weight: 500;
  text-align: center;
  color: #ffffff;
}

 .columnbox__item-title-inn .txt.-main {
  font-size: clamp(34px, 2.75vw, 44px);
  font-weight: 500;
  line-height: 1.2;
  color: #ffffff;
  white-space: nowrap;
}

 .columnbox__item-title-inn .tag {
  margin-right: 10px;
  padding: 2px 12px;
  color: #c8a5d6;
  border-radius: 12px;
  background: #ffffff;
}

 .columnbox__item-details p {
  font-size: clamp(14px, 1vw, 16px);
  font-weight: 500;
  line-height: 1.75;
  max-width: 416px;
  margin: 0 auto;
  color: #ffffff;
}

 .columnbox__item-buttons {
  display: flex;
  flex-wrap: wrap;
  justify-content: start;
  align-content: start;
  gap: 1em;
}

 .columnbox__item-button {
  font-size: clamp(14px, 1vw, 16px);
  font-weight: 700;
  line-height: 1.75;
  color: #ffffff;
  position: relative;
  width: 100%;
  margin: 0;
  background: none;
  cursor: pointer;
  overflow: hidden;
  text-align: center;
  vertical-align: middle;
  white-space: nowrap;
  border: none;
  outline: none;
}

 .columnbox__item-button a {
  display: flex;
  justify-content: flex-start;
  align-items: center;
  width: 100%;
  column-gap: 6px;
  text-decoration: none;
  padding: 18px 4px 16px 22px;
  color: #fff;
  font-weight: 700;
  position: relative;
  background: rgba(248, 245, 250, 0.1);
  border-radius: 34px;
  overflow: clip;
  text-align: left;
  box-sizing: border-box;
  transition: color 0.3s;
}

 .columnbox__item-button a:hover {
  color: #0a58ca;
}

 .columnbox__item-button a:hover::after {
  transition: background-position 0.2s ease-out;
  background-position: 10px 0;
  top: 50%;
}

 .columnbox__item-button a::before {
  content: "";
  width: 90%;
  height: 60%;
  position: absolute;
  left: 12px;
  top: 10px;
  background: rgba(248, 245, 250, 0.4);
  border-radius: 24px;
  filter: blur(8px);
  transition: all 0.3s;
}

 .columnbox__item-button a::after {
  content: "";
  display: block;
  width: 10px;
  height: 10px;
  position: absolute;
  top: 50%;
  right: 22px;
  transform: translateY(-50%);
  background-image: url("data:image/svg+xml;charset=utf8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%20512%20512%22%3E%3Cpath%20fill%3D%22%23fff%22%20d%3D%22M502.6%20278.6c12.5-12.5%2012.5-32.8%200-45.3l-160-160c-12.5-12.5-32.8-12.5-45.3%200s-12.5%2032.8%200%2045.3L402.7%20224%2032%20224c-17.7%200-32%2014.3-32%2032s14.3%2032%2032%2032l370.7%200-105.4%20105.4c-12.5%2012.5-12.5%2032.8%200%2045.3s32.8%2012.5%2045.3%200l160-160z%22%2F%3E%3C%2Fsvg%3E");
  background-repeat: repeat-x;
  background-size: 10px 10px;
  background-position: 0 0;
  transition: all 0.3s;
}

 .columnbox__item-button a[target=_blank]>span {
  width: auto;
  height: 1em;
  aspect-ratio: 1/1;
  background-image: url("data:image/svg+xml;charset=utf8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%20512%20512%22%3E%3Cpath%20fill%3D%22%23fff%22%20d%3D%22M290.4%2019.8C295.4%207.8%20307.1%200%20320%200L480%200c17.7%200%2032%2014.3%2032%2032l0%20160c0%2012.9-7.8%2024.6-19.8%2029.6s-25.7%202.2-34.9-6.9L400%20157.3%20246.6%20310.6c-12.5%2012.5-32.8%2012.5-45.3%200s-12.5-32.8%200-45.3L354.7%20112%20297.4%2054.6c-9.2-9.2-11.9-22.9-6.9-34.9zM0%20176c0-44.2%2035.8-80%2080-80l80%200c17.7%200%2032%2014.3%2032%2032s-14.3%2032-32%2032l-80%200c-8.8%200-16%207.2-16%2016l0%20256c0%208.8%207.2%2016%2016%2016l256%200c8.8%200%2016-7.2%2016-16l0-80c0-17.7%2014.3-32%2032-32s32%2014.3%2032%2032l0%2080c0%2044.2-35.8%2080-80%2080L80%20512c-44.2%200-80-35.8-80-80L0%20176z%22%2F%3E%3C%2Fsvg%3E");
  background-repeat: no-repeat;
  background-position-y: center;
  background-size: 80%;
  position: relative;
  top: -0.1em;
}

 .copy {
  width: 100%;
  margin: 0;
  padding-top: 30px;
  padding-bottom: 20px;
  text-align: center;
  font-size: clamp(12px, 0.8125vw, 13px);
  font-weight: 400;
  line-height: 1.75;
  color: #000000;
  background: #f8f5fa;
  box-sizing: border-box;
}

@media screen and (max-width: 1200px) {
   .columnbox {
    background: linear-gradient(to bottom, #c8a5d6 0%, #b292bf 100%);
  }

   .columnbox__bg {
    background-position: top left, bottom right;
    background-size: 35% auto;
  }

   .columnbox__list {
    grid-template-columns: minmax(0, 100%);
  }

   .columnbox__item::after {
    content: none;
  }

   .columnbox__item-buttons {
    justify-content: center;
  }

   .columnbox__item-button {
    max-width: 220px;
  }
}

.simpleFooter__area p {
  margin: 0;
}

.simpleFooter__area img {
  vertical-align: bottom;
}

.simpleFooter__area {
  width: 100%;
  height: auto;
  font-size: 10px;
  color: #091057;
}

.simpleFooter__area,
.simpleFooter__area * {
  box-sizing: border-box;
}

.simpleFooter--top__box {
  width: 100%;
  height: auto;
  background-color: #DBD3D3;
  padding: 2em 0;
}

.simpleFooter--top__box img {
  width: 30%;
  height: auto;
  display: block;
  margin: 0 auto;
}

.simpleFooter--top__box .footerText {
  text-align: center;
  font-size: 1em;
  margin-top: 2em;
}

.simpleFooter--top__box .link__items {
  padding-left: 0;
  margin: 2em 0 0;
  text-align: center;
  list-style: none;
}

.simpleFooter--top__box .link__items .item+.item {
  margin-top: 0.2em;
}

.simpleFooter--top__box .link__items .item a {
  text-decoration: none;
  color: #091057;
}

.simpleFooter--top__box .link__items .item a:hover {
  text-decoration: underline;
}

.simpleFooter--btm__box {
  background-color: #091057;
  width: 100%;
  height: auto;
  padding: 0.4em 0;
}

.simpleFooter--btm__box .copyright {
  font-size: 1em;
  text-align: center;
  color: #fff;
}

.copymark {
  display: inline-block;
  vertical-align: middle;
}

video {
  margin: 0 !important;
  vertical-align: bottom;
}

.floatingVideo__area {
  position: fixed;
  bottom: 20px;
  left: 20px;
  width: 300px;
  border-radius: 8px;
  overflow: hidden;
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.3);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s ease;
  z-index: 9999;
}

.floatingVideo__area video {
  width: 100%;
  display: block;
}

.floatingVideo__area .close-btn {
  position: absolute;
  top: 5px;
  right: 5px;
  background: rgba(0, 0, 0, 0.6);
  color: #fff;
  border: none;
  border-radius: 50%;
  width: 24px;
  height: 24px;
  cursor: pointer;
  font-size: 16px;
  line-height: 0.1;
  text-align: center;
  z-index: 99999;
}

.floatingVideo__area .overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.4);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  opacity: 0;
  transition: opacity 0.3s ease;
  cursor: pointer;
}

.floatingVideo__area:hover .overlay {
  opacity: 1;
}

#glightbox-body .gprev,
#glightbox-body .gnext {
  display: none !important;
}

.footer-fixed {
  position: fixed;
  font-size: 16px;
  width: 100%;
  height: auto;
  background: rgba(6, 166, 72, .25);
  left: 0;
  bottom: 0;
  padding: 1.5em 0;
  opacity: 1;
  translate: 0 0;
  transition: .3s;
  z-index: 1000;
}

.footer-fixed.init {
  opacity: 0;
  translate: -200px 0;
  pointer-events: none;
}

.footer-fixed.is-scrolled {
  position: fixed;
  opacity: 1;
  translate: 0 0;
  pointer-events: all;
  transition: 1.5s;
}

.footer-fixed-copy {
  text-align: center;
  font-weight: 600;
  font-size: 1.3em;
  margin-bottom: 0.5em;
  color: #333;
}

.footer-fixed-btn .btn {
  display: block;
  text-decoration: none;
  box-sizing: border-box;
  color: #fff;
  background-color: #06a648;
  box-shadow: 0 5px 0 #026d2f;
  border-radius: 0.5em;
  font-size: 1.5em;
  font-weight: 600;
  line-height: 1;
  padding: 1em 2.5em;
  width: fit-content;
  position: relative;
  top: 0px;
  margin: auto;
  text-align: center;
  transition: 0.25s;
}

.footer-fixed-btn .btn.is-animation {
  animation: btnAnimation 2s infinite;
}

.modal-container {
  background-color: #fff;
  width: min(750px, 90vw);
  height: fit-content;
  position: fixed;
  top: 50%;
  left: 50%;
  translate: -50% -50%;
  z-index: 1001;
  font-size: 16px;
  padding: 2em;
  transition: opacity .3s;
  transition-delay: .15s;
  opacity: 0;
  pointer-events: none;
}

.modal-close {
  width: 2.5em;
  aspect-ratio: 1;
  background-color: #000;
  border-radius: 50%;
  position: absolute;
  top: -1.25em;
  right: -1.25em;
  cursor: pointer;
}

.modal-close::before,
.modal-close::after {
  content: '';
  width: 1em;
  height: 2px;
  background-color: #fff;
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}

.modal-close::before {
  transform: translate(-50%, -50%) rotate(45deg);
}

.modal-close::after {
  transform: translate(-50%, -50%) rotate(-45deg);
}

.modal-inner-title {
  font-size: 1.25em;
  font-weight: 600;
  text-align: center;
}

.modal-overlay {
  width: 100vw;
  height: 100vh;
  background-color: rgba(0, 0, 0, 0.5);
  position: fixed;
  top: 0;
  left: 0;
  z-index: 1000;
  transition: opacity .3s;
  opacity: 0;
  pointer-events: none;
}

.btn-column {
  display: grid;
  grid-template-columns: repeat(2, auto);
  gap: 1em 1.5em;
  margin-top: 1em;
}

.btn-column .btn {
  display: block;
  text-decoration: none;
  text-align: center;
  color: #fff;
  background-color: #06a648;
  box-shadow: 0 5px 0 #026d2f;
  font-weight: 600;
  padding: 1em;
  line-height: 1.35;
  border-radius: 99px;
  transition: translate 0.25s, box-shadow 0.25s;
}

.btn-column .btn:hover {
  translate: 0 3px;
  box-shadow: 0 2px 0 #013e52;
}

.is-hide {
  opacity: 0;
  pointer-events: none;
}

.is-show {
  opacity: 1;
  pointer-events: all;
}

button {
  border: none;
  outline: none;
  background: none;
  cursor: pointer;
  display: block;
}


@media (max-width: 560px) {
  .footer-fixed {
    font-size: 3vw;
  }

  .footer-fixed-btn .btn {
    max-width: 80%;
  }

  .modal-container {
    font-size: 3vw;
  }
}

@keyframes btnAnimation {
  0% {
    box-shadow: 0 5px 0 #026d2f;
    top: 0px;
  }

  10% {
    box-shadow: 0 0 0 #026d2f;
    top: 5px;
  }

  20% {
    box-shadow: 0 5px 0 #026d2f;
    top: 0px;
  }

  30% {
    box-shadow: 0 0 0 #026d2f;
    top: 5px;
  }

  40% {
    box-shadow: 0 5px 0 #026d2f;
    top: 0px;
  }
}

[data-editor-view="1"] {
  opacity: 1;
}

p {
  margin: 0;
}

@media screen and (min-width: 601px) {
  .footContact__area {
    display: none;
  }

  .footContact__area.EDITABLE {
    display: block;
  }
}

.footContact__area {
  position: fixed;
  left: 0;
  bottom: 0;
  width: 100%;
  height: auto;
  background-color: #333;
  padding: 5px 0;
  font-size: 12px;
  z-index: 99999;
}

.head__box {
  width: 60%;
  height: auto;
  padding: 5px 0;
  border-radius: 10vw;
  background-color: #fff;
  margin: 0 auto 10px;
  position: relative;
}

.head__box:before {
  content: '';
  position: absolute;
  bottom: -8px;
  left: 50%;
  transform: translateX(-50%);
  display: inline-block;
  width: 0;
  height: 0;
  border-style: solid;
  border-width: 10px 10px 0px 10px;
  border-color: #fff transparent transparent transparent;
}

.head__box .head {
  font-size: 1.1em;
  text-align: center;
  color: #333;
  font-weight: bold;
}

.subHead {
  margin-top: 1.5em;
  font-size: 1.1em;
  text-align: center;
  color: #fff;
}

.subHead ._bold {
  font-size: 1.2em;
  color: #fff;
}

.subHead ._dot {
  position: relative;
}

.subHead ._dot:before {
  content: '';
  width: 4px;
  height: 4px !important;
  border-radius: 2px;
  background-color: #C7243A;
  position: absolute;
  top: -8px;
  left: 50%;
  transform: translateX(-50%);
}

.btn__box {
  margin-top: 1.5em;
  width: 100%;
  height: auto;
  display: flex;
  justify-content: space-evenly;
  align-items: flex-end;
}

.btn__box .btn {
  width: 49%;
  height: auto;
  background-color: #fff;
  font-size: 1.8em;
  font-weight: bold;
  color: #333;
  text-align: center;
  padding: 0.3em 0;
  display: block;
  border-radius: 10vw;
  text-decoration: none;
}

.btn__box .btn.msgArea {
  position: relative;
}

.btn__box .btn.msgArea::before {
  content: 'テキ\aスト';
  color: #fff;
  font-size: 0.6em;
  line-height: 1.1;
  position: absolute;
  top: -2em;
  left: 0;
  width: 3em;
  height: 3em !important;
  padding: 0.4em;
  border-radius: 1.8em;
  background-color: #CAA846;
  white-space: pre;
  transform: rotate(-10deg);
  display: flex;
  justify-content: center;
  align-items: center;
}

.footer {
  font-size: 16px;
  background: #fff;
  padding: 2.8em 0;
  text-align: center;
  color: #00243B;
}

.logo {
  margin: 0 auto;
  width: fit-content;
}

.footer-links {
  margin: 1.25em 0 1.5em;
}

.footer-links ul {
  display: flex;
  justify-content: center;
  align-items: center;
}

.footer-links ul li a {
  border-right: 1px solid #00243B;
  color: #00243B;
  display: inline-block;
  font-size: 11px;
  padding: 0 1.25em;
  text-decoration: none;
}

.copyright {
  font-size: 11px;
  font-weight: 500;
}

ul {
  list-style: none;
  margin: 0;
  padding: 0;
}

img {
  width: 100%;
  height: auto;
}

.footer {
  font-size: 16px;
  width: min(750px, 100%);
  margin-inline: auto;
  background-color: #ffff;
  padding: 1.25em 0;
  text-align: center;
  border-top: 1px solid #ddd;
}

.footer-links {
  display: flex;
  justify-content: center;
  gap: 1.25em;
}

.footer-links a {
  color: #333;
  text-decoration: none;
  font-size: 0.75em;
  transition: color 0.3s ease;
}

.footer-links a:hover {
  color: #0078d4;
}

@media (max-width: 500px) {
  .footer {
    font-size: 3vw;
  }
}

.footBtn__area {
  position: fixed;
  bottom: 1em;
  right: 1em;
  display: flex;
  justify-content: flex-end;
  align-items: center;
  font-size: 16px;
}

@media screen and (max-width:600px) {
  .footBtn__area {
    font-size: 12px;
  }
}

.footBtn__area .footBtn-count__box {
  background-color: #fff;
  padding: 0.3em 0.5em;
  margin-right: 15px;
  box-shadow: 0 0 8px rgba(0, 0, 0, 0.3);
  border-radius: 3px;
  display: flex;
  justify-content: center;
  align-items: center;
  position: relative;
}

.footBtn__area .footBtn-count__box:after {
  content: '';
  position: absolute;
  right: -10px;
  top: 50%;
  transform: translateY(-50%);
  width: 0;
  height: 0;
  border-style: solid;
  border-top: 5px solid transparent;
  border-bottom: 5px solid transparent;
  border-left: 10px solid #ffffff;
  border-right: 0;
}

.footBtn__area .footBtn-count__box .footBtn-countTime__content {
  background: #F9E3AA;
  padding: 0.1em 0.3em;
  margin-right: 0.5em;
}

.footBtn__area .footBtn-count__box .footBtn-countTime__content .time {
  font-size: 0.9em;
  color: #C7243A;
  font-weight: bold;
}

.footBtn__area .footBtn-count__box .footBtn-countText__content .text {
  font-size: 1em;
  font-weight: bold;
  color: #333;
}

.footBtn__area .footBtn-button__box .presentBtn {
  border: none;
  background: #DA6272;
  border-radius: 10vw;
  width: 4em;
  height: 4em !important;
  box-shadow: 0 3px 3px rgba(0, 0, 0, 0.2);
  cursor: pointer;
  display: flex;
  justify-content: center;
  align-items: center;
}

.footBtn__area .footBtn-button__box .presentBtn img {
  width: 100%;
  height: auto;
  max-width: 30px;
  margin: 0 auto;
}

.is-hidden {
  display: none !important;
}

.footerRollItems__area {
  margin: 0 calc(50% - 50vw);
  width: 100vw;
  height: 50px;
  max-width: none;
  box-sizing: border-box;
  overflow-y: hidden;
  position: fixed;
  bottom: 0;
  left: 0;
  text-align: center;
}

.text {
  font-size: 16px;
  font-weight: bold;
  margin: 0;
}

@media screen and (max-width: 600px) {
  .text {
    font-size: 14px;
  }
}

.currentCount__box {
  width: 100%;
  height: 50px !important;
  background: #000;
}

.currentCount__box .text {
  color: #fff;
  line-height: 50px;
}

