  height: auto;
}



/* 背景がピンクの見出し部分の設定 */
.head {
  /* 背景色 */
  background: #df5c88;
  /* 文字色 */
  color: #fff;
  /* 文字の大きさ */
  font-size: 28px;
  /* 文字の太さ */
  font-weight: bold;
  /* 内側の余白｜上余白｜左余白｜下余白｜右余白｜ */
  padding: 15px 20px 15px 65px;
  position: relative;
}



/* 見出しのアイコンの共通設定 */
.icon-crown:before,
.icon-list:before {
  content: '';
  position: absolute;
  /* 表示位置（上基準） */
  top: 50%;
  /* 表示位置（左基準） */
  left: 20px;
  /* 表示位置（Y軸） */
  transform: translateY(-50%);
  /* 横幅 */
  width: 36px;
  /* 高さ */
  height: 32px;
}



/* 王冠画像の設定 */
.icon-crown:before {
  /* 王冠の画像 */
  background: url('/uploads/aa17d5d5c9ab8c93d0d024dfecb399c7c3fe661e46738c44b6cf0fed47f9fcca.png') no-repeat;

}



/* リスト画像の設定 */
.icon-list:before {
  /* リストの画像 */
  background: url('/uploads/73d3e0ac70378999b650b1886eac5e567cc18c8cfff7ac2604cf52f557bf5e2f.png') no-repeat;
}



/* メニューの箱（アコーディオン部分も含む） */
.items,
.accordionItems {
  /* 内側の余白 */
  padding: 0;
  /* 外側の余白 */
  margin: 0;
  /* 横幅 */
  width: 100%;
  /* 高さ */
  height: auto;
  /* リストスタイル */
  list-style: none;
}



/* アコーディオン部分の初期設定 */
.accordionItems {
  /* 非表示 */
  display: none;
}



/* メニュー1行の設定 */
.items .item {
  /* 横幅 */
  width: 100%;
  /* 高さ */
  height: auto;
  /* 下線｜太さ｜線種｜色｜ */
  border-bottom: 1px solid #df5c88;
  /* 背景色 */
  background: #fcfaee;
}



/* メニューのリンク（アコーディオン部分含む） */
.items .item a,
.items .item .accordionHead {
  display: block;
  /* 下線 */
  border-bottom: none;
  /* 内側の余白 */
  padding: 20px;
  /* 文字色 */
  color: #333;
  /* テキストデコレーション */
  text-decoration: none;
  /* アニメーションの速さ */
  transition: .3s;
  /* カーソルが対象に触れると指になる */
  cursor: pointer;
  /* 文字の大きさ */
  font-size: 25px;
  /* 文字の太さ */
  font-weight: bold;
  /* 行間 */
  line-height: 1.4;
}



/* アコーディオン内のリンク */
.items .item.accordion .accordionItems .item a {
  /* 内側の余白｜上下余白｜左右余白｜ */
  padding: 10px 40px;
}



/* リンクに触れた際の設定（アコーディオン含む） */
.items .item a:hover,
.items .item .accordionHead:hover {
  /* 透明度 */
  opacity: 0.7;
}



/* リンク左側の矢印 */
.items .item a:before,
.items .item.accordion .accordionHead:before {
  content: '';
  display: inline-block;
  /* 外側の余白｜上余白｜右余白｜下余白｜左余白｜ */
  margin: 0 12px 0 0;
  /* 横幅 */
  width: 14px;
  /* 高さ */
  height: 14px;
  /* 矢印の線の太さ、線種、色 */
  border-top: 5px solid #df5c88;
  border-right: 5px solid #df5c88;
  /* 回転 */
  transform: rotate(45deg);
  /* アニメーションの速さ */
  transition: 0.3s transform;
}



/* アコーディオンが開いた時の設定 */
.items .item.accordion .accordionHead.active:before {
  /* 外側の余白｜上余白｜右余白｜下余白｜左余白｜ */
  margin: 0 12px 4px 0;
  /* 回転 */
  transform: rotate(135deg);
}



/* アコーディオンを内包する親リンク部分 */
.items .item.accordion {
  /* 内側の余白 */
  padding: 0;
  /* 下線 */
  border-bottom: none;
}



/* アコーディオンの見出し部分 */
.items .item.accordion .accordionHead {
  /* 横幅 */
  width: calc(100% - 40px);
  /* 内側の余白 */
  padding: 20px;
  display: inline-block;
  /* 下線 */
  border-bottom: 1px solid #df5c88;
}

/* 画面サイズ600px以下の設定（任意） */
@media screen and (max-width: 600px) {


  /* 背景がピンクの見出し部分の設定 */
  .head {
    /* 文字の大きさ */
    font-size: 14px;
    /* 文字の太さ */
    font-weight: bold;
    /* 内側の余白 */
    padding: 10px 10px 10px 35px;
  }



  /* 見出しのアイコンの共通設定 */
  .icon-crown:before,
  .icon-list:before {
    left: 10px;
    /* 横幅 */
    width: 18px;
    /* 高さ */
    height: 16px;
    background-size: 100%;
  }



  /* メニューのリンク（アコーディオン部分含む） */
  .items .item a,
  .items .item .accordionHead {
    /* 内側の余白 */
    padding: 10px;
    /* 文字の大きさ */
    font-size: 14px;
  }



  /* アコーディオン内のリンク */
  .items .item.accordion .accordionItems .item a {
    /* 内側の余白 */
    padding: 10px 20px;
  }



  /* メニューのリンク（アコーディオン部分） */
  .items .item.accordion .accordionHead {
    /* 横幅 */
    width: calc(100% - 20px);
    /* 内側の余白 */
    padding: 10px;
  }



  /* リンクに触れた際の設定（アコーディオン含む） */
  .items .item a:before,
  .items .item.accordion .accordionHead:before {
    /* 外側の余白 */
    margin: 0 6px 0 0;
    /* 横幅 */
    width: 7px;
    /* 高さ */
    height: 7px;
    /* 矢印の線の太さ、線種、色 */
    border-top: 3px solid #df5c88;
    border-right: 3px solid #df5c88;
  }



  /* アコーディオンが開いた時の設定 */
  .items .item.accordion .accordionHead.active:before {
    /* 外側の余白 */
    margin: 0 6px 2px 0;
  }
}

.message-bottom {
  position: fixed;
  /* 表示位置（下基準） */
  bottom: 0;
  /* 表示位置（左基準） */
  left: 0;
