}

.inner {
  position: relative;
  /* 高さ */
  height: 41px;
  /* 外側の余白 */
  margin: 0;
}

div {
  /* 外側の余白 */
  margin: 0;
  /* 内側の余白 */
  padding: 0;
  /* 線 */
  border: 0;
  vertical-align: baseline;
  box-sizing: border-box;
  -webkit-tap-highlight-color: rgba(0, 0, 0, 0);
}

.item {
  position: absolute;
  /* 表示位置（上基準） */
  top: 0;
  /* 表示位置（左基準） */
  left: 0;
  box-sizing: border-box;
  /* 横幅 */
  width: 100%;
  /* 内側の余白 */
  padding: 0;
  display: block;
}

.swiper-container {
  overflow: hidden;
  /* 横幅 */
  width: 100%;
  /* 高さ */
  height: 42px;
}

.swiper-wrapper {
  transform: translate3d(0, 0, 0);
  position: relative;
  /* 横幅 */
  width: 100%;
  /* 高さ */
  height: 100%;
  z-index: 1;
  display: flex;
  -ms-transition-property: -ms-transform;
  transition-property: transform;
  box-sizing: content-box;
}

.slide {
  /* 内側の余白 */
  padding: 7px 20px 10px 20px;
  /* 外側の余白 */
  margin: 0;
  flex-shrink: 0;
  /* 横幅 */
  width: 100%;
  /* 高さ */
  height: 100%;
  position: relative;
  /*背景色*/
  background-color: #4b4b4b;
  text-align: center;
}

.item p {
  /*文字サイズ*/
  font-size: 12px;
  text-shadow: none;
  /*時間スペース*/
  letter-spacing: .1em;
  /* 内側の余白 */
  padding: 0;
  /* 外側の余白 */
  margin: 0;
  /*文字の色*/
  color: #fff;
  /*文字の太さ*/
  font-weight: 600;
}



/*○名部分*/
.item span {
  /*文字サイズ*/
  font-size: 18px;
  /*文字の太さ*/
  font-weight: bold;
  font-style: normal;
  display: inline-block;
  vertical-align: -1px;
  /* 外側の余白 */
  margin: 0;
  /* 内側の余白 */
  padding: 0;
  /* 線 */
  border: 0;
  box-sizing: border-box;
  -webkit-tap-highlight-color: rgba(0, 0, 0, 0);
}

.parent__area {
  position: relative;
}

.num {
  /*○名の文字色*/
  color: #ff0000;
  position: absolute;
  /* 表示位置（上基準） */
  top: 0;
  /* 表示位置（左基準） */
  left: 0;
}

.item span.parent__area {
  /* 横幅 */
  width: 2em;
  /* 高さ */
  height: 1.2em;
  overflow: hidden;
}

.num.animeDefaultPlus {
  /*アニメーションの設定｜アニメーション名｜1回のサイクルに要する時間｜進め方｜実行回数｜*/
  animation: down 0.5s ease-in 1;
}

.num.animePlus {
  /*アニメーションの設定｜アニメーション名｜1回のサイクルに要する時間｜進め方｜実行回数｜*/
  animation: nextDown 0.5s ease-in 1;
}

.num.is-posiTop {
  position: absolute;
  /* 表示位置（上基準） */
  top: -2rem;
  /* 表示位置（左基準） */
  left: 0;
}

.num.animeDefaultMinus {
  /*アニメーションの設定｜アニメーション名｜1回のサイクルに要する時間｜進め方｜実行回数｜*/
  animation: up 0.5s ease-in 1;
}

.num.animeMinus {
  /*アニメーションの設定｜アニメーション名｜1回のサイクルに要する時間｜進め方｜実行回数｜*/
  animation: nextUp 0.5s ease-in 1;
}

.num.is-posiBtm {
  position: absolute;
  /* 表示位置（上基準） */
  top: 2rem;
  /* 表示位置（左基準） */
  left: 0;
}

@keyframes down {
  0% {
    /* 表示位置（上基準） */
    top: 0;
  }

  100% {
    /* 表示位置（上基準） */
    top: 2rem;
  }
}

@keyframes nextDown {
  0% {
    /* 表示位置（上基準） */
    top: -2rem;
  }

  100% {
    /* 表示位置（上基準） */
    top: 0;
  }
}

@keyframes up {
  0% {
    /* 表示位置（上基準） */
    top: 0;
  }

  100% {
    /* 表示位置（上基準） */
    top: -2rem;
  }
}

@keyframes nextUp {
  0% {
    /* 表示位置（上基準） */
    top: 2rem;
  }

  100% {
    /* 表示位置（上基準） */
    top: 0;
  }
}

